import {createTransportStaff,poseTransportStaff,disposeTransportStaff} from '../residents/transport-staff.js';
export const AIRPORT_GUIDE=Object.freeze({id:'airport-sugar-glider',x:19.4,y:.05,z:-11.6,yaw:Math.PI/2,radius:.70});
const target=Object.freeze({id:'resident.airport-sugar-glider',type:'resident',residentId:'airport-sugar-glider',at:{x:21,z:-11.6},radius:.72,requiresClearApproach:true,label:'슈가글라이더 안내원과 이야기하기',name:'슈가글라이더 안내원',role:'마을 비행장 안내',text:'밝은 길을 따라 작은 비행기에 오르면 구름성 놀이섬에 갈 수 있어요. 자리에 앉은 뒤 출발을 눌러요. 비행장 벤치에서는 쉬고 있는 비행기를 바라볼 수 있어요.'});
/** Nearby-only optional actor. The plane's readiness never depends on this load. */
export function createAirportStaff({root,load=()=>createTransportStaff('airport-sugar-glider')}={}){
 let alive=true,generation=0,pending=null,model=null,wanted=false,failed=false,time=0,updates=0,lastDistance=Infinity,appeared=false,selected=true;
 const remove=()=>{if(model){disposeTransportStaff(model);model=null;appeared=false;}};
 function start(){const ticket=++generation;pending=Promise.resolve().then(()=>alive&&ticket===generation&&wanted?load():null).then(next=>{if(!next)return false;if(!alive||ticket!==generation||!wanted){disposeTransportStaff(next);return false;}model=next;model.position.set(AIRPORT_GUIDE.x,AIRPORT_GUIDE.y,AIRPORT_GUIDE.z);model.rotation.y=AIRPORT_GUIDE.yaw;appeared=lastDistance>=1.48;model.visible=appeared&&selected;root.add(model);poseTransportStaff(model);return true;}).catch(()=>{if(alive&&ticket===generation)failed=true;return false;}).finally(()=>{if(ticket===generation)pending=null;});}
 function reconcile(position,{selected:nextSelected=true}={}){if(!alive||!position)return Infinity;const reveal=!selected&&!!nextSelected;selected=!!nextSelected;const distance=Math.hypot(position.x-AIRPORT_GUIDE.x,position.z-AIRPORT_GUIDE.z);lastDistance=distance;if(reveal&&distance<1.48)appeared=false;if(distance>22){wanted=false;failed=false;if(pending){generation++;pending=null;}remove();return distance;}wanted=distance<=15||wanted;if(wanted&&!model&&!pending&&!failed)start();if(model){if(!appeared&&distance>=1.48)appeared=true;model.visible=appeared&&distance<=18&&selected;}return distance;}
 return{reconcile,update(dt,position,{paused=false,reducedMotion=false,selected=true}={}){const distance=reconcile(position,{selected});if(!model||!model.visible||distance>12||paused||!Number.isFinite(dt)||dt<=0||root.visible===false)return;time+=Math.min(dt,.05);poseTransportStaff(model,{mode:distance<2.8?'greeting':'idle',time,reducedMotion});updates++;},interactions:()=>model?.visible?[target]:[],circles:()=>model?.visible?[{id:target.id,x:AIRPORT_GUIDE.x,z:AIRPORT_GUIDE.z,radius:AIRPORT_GUIDE.radius}]:[],whenSettled:()=>pending??Promise.resolve(!!model),snapshot:()=>({ready:!!model,visible:!!model?.visible,loading:!!pending,failed,updates,time,mode:model?.userData.mode??null}),dispose(){if(!alive)return;alive=false;wanted=false;generation++;pending=null;remove();}};
}
